<script setup>
import {ref,onMounted,onUnmounted} from 'vue'
import {api,post,formatTimestamp} from './quotationApi'
const emit=defineEmits(['excel','drafts','ai'])
const limits=ref(null),batches=ref([]),detail=ref(null),selection=ref([]),error=ref(''),message=ref(''),busy=ref(false),progress=ref(''),task=ref(null),imageUrl=ref(''),imageName=ref(''),classifications=ref({}),confirmedSamples=ref({}),aiCalls=ref(null)
const labels={waiting:'等待提取',processing:'正在提取',success:'提取成功',failed:'提取失败',draft:'草稿',pending:'待审批',approved:'已入库',rejected:'已驳回',withdrawn:'已撤回'}
let timer=null,alive=true
async function run(fn){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false;progress.value=''}}
async function list(){batches.value=(await api('/api/uploads/batches')).items}
async function open(id){detail.value=await api('/api/uploads/batches/'+id);task.value=null}
function closeImage(){if(imageUrl.value)URL.revokeObjectURL(imageUrl.value);imageUrl.value=''}
function choose(e){selection.value=Array.from(e.target.files||[]);error.value=''}
async function upload(){
 if(!selection.value.length)throw new Error('请先选择文件')
 if(selection.value.length>limits.value.max_batch_files)throw new Error(`单批最多${limits.value.max_batch_files}个文件`)
 if(selection.value.some(f=>f.size>limits.value.max_file_bytes))throw new Error('存在超过大小限制的文件，请调整后重选')
 const batch=await post('/api/uploads/batches',{});const notices=[];let created=0;let originalBatch=null
 for(let i=0;i<selection.value.length;i++){
  const f=selection.value[i];progress.value=`正在上传 ${i+1}/${selection.value.length}：${f.name}`
  try{const r=await api(`/api/uploads/batches/${batch.id}/files?filename=${encodeURIComponent(f.name)}`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:f,signal:AbortSignal.timeout(120000)});if(r.duplicate){notices.push(`${f.name}：同一原件已存在，未重复保存`);originalBatch=r.batch_id}else created++}catch(e){notices.push(`${f.name}：${e.message}`)}
 }
 message.value=`本批保存${created}个原件。${notices.join('；')}`;selection.value=[];await list();if(created)await open(batch.id);else if(originalBatch)await open(originalBatch)
}
async function extract(f){await post(`/api/uploads/files/${f.id}/extract`,{});await open(detail.value.batch.id);message.value='提取任务已登记，离开页面后仍会继续。'}
async function inspect(f){task.value=await api('/api/uploads/tasks/'+f.task.id);aiCalls.value=(await api('/api/ai/tasks/'+f.task.id+'/calls')).items}
function needsConsent(f){return limits.value?.ai.ready&&!f.ai_consent&&(f.metadata.kind!=='xlsx'||f.task?.error_code==='AI_SCOPE_REQUIRED')}
function statusLabel(f){return f.task?.error_code==='AI_SCOPE_REQUIRED'?'等待文件发送确认（尚未调用AI）':f.task?labels[f.task.status]:'尚未提取'}
async function consentAndExtract(f){await consent(f);await extract(f)}
async function consent(f){if(!classifications.value[f.id]||!confirmedSamples.value[f.id])throw new Error('请先选择文件的真实性质，并确认允许发送；真实报价当前不允许外发');await post(`/api/ai/files/${f.id}/consent`,{classification:classifications.value[f.id],confirmed:!!confirmedSamples.value[f.id]});await open(detail.value.batch.id);message.value='已保存此文件的样本声明；只会向显示的DeepSeek服务发送。'}
async function revoke(f){await post(`/api/ai/files/${f.id}/consent`,{classification:'none',confirmed:false});await open(detail.value.batch.id);message.value='已撤销后续外发授权；已发送内容无法撤回。'}
async function showImage(f){const r=await fetch(`/api/uploads/files/${f.id}/original`);if(!r.ok)throw new Error((await r.json()).error?.message||'无法读取原件');if(imageUrl.value)URL.revokeObjectURL(imageUrl.value);imageUrl.value=URL.createObjectURL(await r.blob());imageName.value=f.original_name}
async function poll(){
 if(!alive)return
 try{if(detail.value?.files.some(f=>['waiting','processing'].includes(f.task?.status))){const id=detail.value.batch.id;const fresh=await api('/api/uploads/batches/'+id);if(alive&&detail.value?.batch.id===id){detail.value=fresh;if(task.value)task.value=await api('/api/uploads/tasks/'+task.value.id)}}}catch(e){if(alive)error.value='任务状态刷新失败，可点击刷新重试：'+e.message}
 if(alive)timer=setTimeout(poll,1500)
}
onMounted(()=>{run(async()=>{limits.value=await api('/api/uploads/limits');await list()});poll()})
onUnmounted(()=>{alive=false;clearTimeout(timer);if(imageUrl.value)URL.revokeObjectURL(imageUrl.value)})
</script>
<template><section>
<div class="catalog-heading"><div><h2>上传原件与提取任务</h2><p>先保存原件，再点击提取报价；提取结果须校对和审批才能发布。</p></div><div class="form-actions"><button class="small-button" @click="emit('drafts')">返回草稿校对</button><button class="small-button" @click="emit('excel',null)">固定Excel模板导入</button></div></div>
<p class="quote-banner">固定Excel模板优先本机解析。PDF、图片及其他表格可用DeepSeek提取；当前仅允许虚构或已脱敏样本，真实报价暂不外发。</p>
<p v-if="limits" class="catalog-note">支持 XLSX、PDF、JPG、JPEG、PNG；单文件不超过{{limits.max_file_bytes/1024/1024}}MB，每批最多{{limits.max_batch_files}}个，PDF最多{{limits.max_pdf_pages}}页。旧版XLS请另存为XLSX。公式不执行，含公式的价格需人工核对。</p>
<p v-if="limits?.ai">AI服务：{{limits.ai.provider}} · {{limits.ai.model}} · {{limits.ai.endpoint}} · {{limits.ai.ready?'已启用':'尚未启用或未配置密钥'}}</p><div class="upload-box"><label>选择报价原件<input type="file" multiple accept=".xls,.xsl,.xlsx,.pdf,.jpg,.jpeg,.png" :disabled="busy" @change="choose"></label><p>已选择{{selection.length}}个文件：{{selection.map(f=>f.name).join('、')}}</p><button class="small-button primary" :disabled="busy||!limits||!selection.length" @click="run(upload)">{{busy?'正在处理…':'保存本批原件'}}</button><p role="status">{{progress}}</p></div>
<p v-if="error" class="feedback error" role="alert">{{error}}</p><p v-if="message" class="feedback success" role="status">{{message}}</p>
<div class="upload-layout"><aside><h3>已上传批次</h3><button class="small-button" :disabled="busy" @click="run(async()=>{await list();if(detail)await open(detail.batch.id)})">刷新列表与状态</button><p v-if="!batches.length">暂无上传原件。</p><button v-for="b in batches" :key="b.id" class="upload-batch small-button" :disabled="busy" @click="run(()=>open(b.id))">{{b.file_count}}个文件 · {{labels[b.status]}}<br><small>{{b.id.slice(0,10)}} · {{formatTimestamp(b.created_at)}}</small></button></aside>
<section v-if="detail"><h3>批次 {{detail.batch.id.slice(0,10)}} · {{labels[detail.batch.status]}}</h3><article v-for="f in detail.files" :key="f.id" class="upload-card"><h3>{{f.original_name}}</h3><p>{{(f.size_bytes/1024).toFixed(1)}} KB · {{formatTimestamp(f.created_at)}} <span v-if="f.metadata.pages">· {{f.metadata.pages}}页</span><span v-if="f.metadata.width">· {{f.metadata.width}}×{{f.metadata.height}}</span></p><p>提取状态：<b>{{statusLabel(f)}}</b><span v-if="f.task"> · 已尝试{{f.task.attempts}}次 · {{formatTimestamp(f.task.updated_at)}}</span></p><p v-if="f.task?.error_code==='AI_SCOPE_REQUIRED'" class="quote-banner">此文件尚未发送给AI。请先选择文件性质，再勾选发送确认，点击下方“确认样本并提取”。真实报价暂不允许发送。</p><p v-else-if="f.task?.error" class="feedback error">{{f.task.error}}</p><p v-if="f.task?.result">识别到{{f.task.result.counts?.total||0}}行报价，其中{{f.task.result.counts?.importable||0}}行可保存为草稿。尚未入库。</p><div v-if="limits?.ai.ready&&!f.task?.result?.ai_import_id&&['draft','rejected','withdrawn'].includes(detail.batch.status)" class="sample-consent"><template v-if="!f.ai_consent"><p>如需使用AI，须先确认此文件为虚构或已脱敏样本。所选文件内容将发送到 {{limits.ai.endpoint}}，模型 {{limits.ai.model}}。</p><label>样本性质<select v-model="classifications[f.id]"><option disabled :value="undefined">请选择文件性质</option><option value="synthetic">虚构测试资料</option><option value="redacted">已脱敏资料</option></select></label><label><input type="checkbox" v-model="confirmedSamples[f.id]">我确认此文件符合上述样本范围，允许发送到此DeepSeek接口用于提取</label><button class="small-button" :disabled="busy||!confirmedSamples[f.id]||!classifications[f.id]" @click="run(()=>consent(f))">仅保存样本声明</button></template><template v-else><p>已确认：{{f.ai_consent.classification==='synthetic'?'虚构样本':'已脱敏样本'}}；发送至DeepSeek。</p><button class="small-button" :disabled="busy" @click="run(()=>revoke(f))">撤销后续外发授权</button></template></div><div class="form-actions"><a class="small-button" :href="`/api/uploads/files/${f.id}/original`" download>下载原件</a><button v-if="f.media_type.startsWith('image/')" class="small-button" :disabled="busy" @click="run(()=>showImage(f))">查看图片</button><button v-if="!f.task||f.task.status==='failed'" class="small-button primary" :disabled="busy||!['draft','rejected','withdrawn'].includes(detail.batch.status)||(needsConsent(f)&&(!confirmedSamples[f.id]||!classifications[f.id]))" @click="run(()=>needsConsent(f)?consentAndExtract(f):extract(f))">{{needsConsent(f)?'确认样本并提取':f.task?'重试提取':'提取报价'}}</button><button v-if="f.task" class="small-button" :disabled="busy" @click="run(()=>inspect(f))">任务结果与重试记录</button><button v-if="f.task?.result?.ai_import_id" class="small-button primary" @click="emit('ai',f.task.result.ai_import_id)">校对AI结果，选择生成草稿</button><button v-if="f.task?.result?.import_id" class="small-button primary" @click="emit('excel',f.task.result.import_id)">校对提取结果，选择生成草稿</button></div><small class="file-hash">原件校验值 SHA256：{{f.sha256}}</small></article></section></div>
<section v-if="imageUrl" class="upload-card"><h3>原件图片 · {{imageName}}</h3><button class="small-button" @click="closeImage">关闭图片</button><img :src="imageUrl" :alt="imageName" style="display:block;max-width:100%;max-height:800px;object-fit:contain"></section>
<section v-if="task" class="upload-card"><h3>提取任务记录 · {{task.original_name}}</h3><p>当前状态：{{labels[task.status]}}，尝试{{task.attempts}}次。原始提取结果与人工草稿分别保存。</p><article v-for="a in task.attempt_history" :key="a.id"><p>第{{a.attempt}}次 · {{labels[a.status]}} · {{formatTimestamp(a.started_at)}} ～ {{formatTimestamp(a.finished_at)}}</p><p>{{a.error}}</p><p v-if="a.result">{{a.result.kind==='ai'?'AI提取':'固定模板解析'}}：共{{a.result.counts.total}}行；可保存{{a.result.counts.importable}}行。<button v-if="a.result.ai_import_id" class="small-button" @click="emit('ai',a.result.ai_import_id)">查看AI原文与位置</button><button v-else class="small-button" @click="emit('excel',a.result.import_id)">查看逐行原文与位置</button></p></article></section><details v-if="aiCalls?.length"><summary>逐次AI原始输出及调用记录</summary><article v-for="c in aiCalls" :key="c.id"><p>第{{c.ordinal}}段 · {{labels[c.status]}} · {{c.error_code}}</p><pre style="white-space:pre-wrap;max-height:400px;overflow:auto">{{c.response?.content}}</pre></article></details>
</section></template>
<style scoped>
.upload-box,.upload-card{background:#fff;border:1px solid #dce5ee;border-radius:12px;padding:20px;margin:16px 0}.upload-box input{display:block;margin-top:12px;max-width:100%}.upload-layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:24px}.upload-batch{display:block;width:100%;white-space:normal;text-align:left;margin-top:12px}.upload-card{overflow-wrap:anywhere}.file-hash{display:block;margin-top:14px;color:#64748b}.upload-card a{text-decoration:none}.upload-card p{line-height:1.7}@media(max-width:800px){.upload-layout{grid-template-columns:1fr}}
</style>
